def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    dp = [[float('inf')] * N for _ in range(N)]
    dp[0][0] = grid[0][0]

    for step in range(1, k + 1):
        for r in range(N):
            for c in range(N):
                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < N and 0 <= nc < N:
                        dp[r][c] = min(dp[r][c], dp[nr][nc] + grid[r][c])

    path = []
    r, c = 0, 0
    for step in range(k):
        path.append(grid[r][c])
        min_val = float('inf')
        min_dir = None
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N and dp[nr][nc] < min_val:
